interface.definition:
a!localVariables(
  local!isOldVersion: if(
    a!isNullOrEmpty(ri!nominationView.createdOn),
    false,
    if(
      todatetime(ri!nominationView.createdOn) < #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false
    )
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
  contents: {
    #"SYSTEM_SYSRULES_columnsLayout"(
      columns: {
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Candidate Name",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: if(
                  and(
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(property(ri!nominationView, "firstName", tostring(null))),
                    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(property(ri!nominationView, "lastName", tostring(null)))
                  ),
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3372378",
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView, "lastName", tostring(null)), isBoolean: false) &
                  ", " &
                  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView, "firstName", tostring(null)),isBoolean: false) &
                  " " &
                  property(ri!nominationView, "middleName", tostring(null))

                )
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Job Function",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"functionName",tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Job Family",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"levelName",tostring(null)), isBoolean: false)
              )
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Employee ID",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"employeeId",tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Job Description",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"jobDescription",tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Current PML",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"currentPml",tostring(null)),
                isBoolean: false)
              )
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Originating Region",
              showWhen: if(toboolean(local!isOldVersion)=true,true,false),
              value:  #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"originatingRegion",tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Originating Audit BU",
              value:  #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"originatingBU",tostring(null)),isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Originating Home Office",
              value:  #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView,"originatingHomeOffice",tostring(null)), isBoolean: false)
              )
            )
          }
        ),
        #"SYSTEM_SYSRULES_columnLayout"(
          contents: {
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Other Originating Region",
              showWhen: if(toboolean(local!isOldVersion)=true,true,false),
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView, "otherOriginatingRegion", tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Other Originating Audit BU",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView, "otherOriginatingBU", tostring(null)), isBoolean: false)
              )
            ),
            #"SYSTEM_SYSRULES_richTextDisplayField"(
              label: "Other Originating Home Office",
              value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: property(ri!nominationView, "otherOriginatingHomeOffice", tostring(null)), isBoolean: false)
              )
            )
          }
        )
      }
    )
  },
  style: "STANDARD"
)
)
